# coding: utf-8
"""Report frozen, user-approved situation-goal 100, without mixing old accuracy measures."""
from pathlib import Path
import json,sys,statistics,math,collections
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[2];OUT=ROOT/'docs/situation-goal100';sys.path.insert(0,str(HERE.parent/'situation_v3'))
from common import usage_counts
run=json.loads((OUT/'run/results.json').read_text());assert run['complete'];prices=json.loads((OUT/'unit-prices.json').read_text())
def describe(rows):
 grouped=collections.defaultdict(lambda:{'calls':0,'input':0,'output':0,'cached_input':0,'estimated_usd':0.,'no_cache_estimated_usd':0.,'unknown_usage_calls':0})
 for r in rows:
  for c in r['calls']:
   assert c.get('http_status')!=429
   role=c['provider'];g=grouped[role];g['calls']+=1;u=usage_counts(c.get('usage'));i,o,cache=u['input'],u['output'],u['cached_input']
   if i is None or o is None:g['unknown_usage_calls']+=1;continue
   g['input']+=i;g['output']+=o
   if role=='e5_jev':g['cached_input']=None;g['estimated_usd']+=i*prices['jev-1.14.0']['input']/1e6;g['no_cache_estimated_usd']+=i*prices['jev-1.14.0']['input']/1e6
   else:
    assert cache is not None and 0<=cache<=i;p=prices['gpt-4.1-2025-04-14'];g['cached_input']+=cache;g['estimated_usd']+=((i-cache)*p['input']+cache*p['cached_input']+o*p['output'])/1e6;g['no_cache_estimated_usd']+=(i*p['input']+o*p['output'])/1e6
 times=sorted(r['http_ms'] for r in rows);n=len(rows)
 return {'n':n,'mean_all_ms':statistics.mean(times),'p95_all_ms':times[math.ceil(.95*n)-1],'stages':dict(grouped),'cost_usd':sum(g['estimated_usd'] for g in grouped.values()),'no_cache_cost_usd':sum(g['no_cache_estimated_usd'] for g in grouped.values()),'input_mean':sum(g['input'] for g in grouped.values())/n,'output_mean':sum(g['output'] for g in grouped.values())/n,'queue_ms':sum(r.get('queue_wait_ms',0) for r in rows)}
summary={};families={};failures={}
for provider,s in run['summary'].items():
 rows=[r for r in run['results'] if r['provider']==provider];x=describe(rows);x.update(accepted_set_correct=s['status_and_menu_correct'],accepted_set_accuracy=s['status_and_menu_accuracy'],required_outcome_recall=s['required_outcome_recall'],allowed_menu_precision=s['allowed_menu_precision'],missing_outcomes=s['missing_outcome_count'],disallowed_menus=s['disallowed_menu_count'],errors=s['errors'],canonical_correct=sum(r['score']['canonical_status_and_menu_exact'] for r in rows));summary[provider]=x
 families[provider]={f:{'title':next(r['situation'] for r in rows if r['family_id']==f),'n':sum(r['family_id']==f for r in rows),'correct':sum(r['score']['status_and_menu_exact'] for r in rows if r['family_id']==f)} for f in sorted({r['family_id'] for r in rows})}
 failures[provider]=[{k:r.get(k) for k in ['case_id','query','expected_ids','acceptable_sets','selected_ids','status','error','score','reviews','calls']} for r in rows if not r['score']['status_and_menu_exact']]
a=summary['hybrid'];b=summary['llm_full_catalog'];diff={'accuracy_pp':(a['accepted_set_accuracy']-b['accepted_set_accuracy'])*100,'mean_http_percent':(a['mean_all_ms']/b['mean_all_ms']-1)*100,'input_percent':(a['input_mean']/b['input_mean']-1)*100,'cost_percent':(a['cost_usd']/b['cost_usd']-1)*100}
result={'summary':summary,'family_results':families,'hybrid_relative_to_llm':diff,'metric':'Exact match to one finite preapproved acceptable menu-ID set plus status. Required outcome recall and allowed-menu precision are separate.','dataset':'100 distinct expressions of 10 user-approved situation families, not 100 independent goals. 50 broad goals +50 circumstances.','price_sources':prices}
(OUT/'summary.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');(OUT/'failures.json').write_text(json.dumps(failures,ensure_ascii=False,indent=2)+'\n')
pct=lambda x:f'{100*x:.2f}%'
lines=['# 상황형 복합 요청 100문항 실제 비교','','사용자가 승인한 상황별 필수·대체·선택 추천 기준으로 새 질문 100개를 만들었다. 두 조건 모두 GPT-4.1-2025-04-14, 같은 585개 메뉴, 최대 8개 출력이다. 삼단계는 고정된 일반 업무 분해 → 실제 E5 → JEV-1.14.0이다. 평가용 정답표는 모델·검색·분기 코드에 넣지 않았다.','', '## 실제 결과','', '| 지표 | LLM→E5→JEV | GPT-4.1 단독 |','|---|---:|---:|',f"| 허용 정답 집합+상태 완전일치 | {a['accepted_set_correct']}/100 · {pct(a['accepted_set_accuracy'])} | {b['accepted_set_correct']}/100 · {pct(b['accepted_set_accuracy'])} |",f"| 필수 업무 Recall | {pct(a['required_outcome_recall'])} | {pct(b['required_outcome_recall'])} |",f"| 허용 메뉴 Precision | {pct(a['allowed_menu_precision'])} | {pct(b['allowed_menu_precision'])} |",f"| 전체 평균 / P95 HTTP ms | {a['mean_all_ms']:,.2f} / {a['p95_all_ms']:,.2f} | {b['mean_all_ms']:,.2f} / {b['p95_all_ms']:,.2f} |",f"| 문항당 입력 / 출력 토큰 | {a['input_mean']:,.2f} / {a['output_mean']:,.2f} | {b['input_mean']:,.2f} / {b['output_mean']:,.2f} |",f"| 캐시 반영 API 비용 추정 /100문항 | ${a['cost_usd']:.4f} | ${b['cost_usd']:.4f} |",f"| 캐시 없이 환산한 API 비용 /100문항 | ${a['no_cache_cost_usd']:.4f} | ${b['no_cache_cost_usd']:.4f} |",f"| 오류(정확도 실패 포함) | {a['errors']} | {b['errors']} |",f"| 누락 필수 업무 / 비허용 추가 메뉴 | {a['missing_outcomes']} / {a['disallowed_menus']} | {b['missing_outcomes']} / {b['disallowed_menus']} |",'',f"삼단계 기준 차이: 정확도 {diff['accuracy_pp']:+.2f}%p, 평균 시간 {diff['mean_http_percent']:+.2f}%, 입력 토큰 {diff['input_percent']:+.2f}%, 캐시 반영 API 비용 {diff['cost_percent']:+.2f}%.",'','## 상황군별 결과','', '| 상황(각 10개 표현) | 삼단계 | 단독 LLM |','|---|---:|---:|']
for f,x in families['hybrid'].items():lines.append(f"| {x['title']} | {x['correct']}/10 | {families['llm_full_catalog'][f]['correct']}/10 |")
lines+=['','## 범위와 해석','', '- 이번 지표는 실행 전에 승인한 여러 메뉴 조합 중 하나와 정확히 일치해야 성공이다. 관련 메뉴면 전부 인정하는 방식이 아니다. 필수 업무 누락·불허 추가·불필요한 중복·오류는 실패다. 단일 기준 메뉴와의 완전일치도 원시 결과에 별도로 남겼다.', '- 이전 95%는 메뉴명 나열/원하는 기능이 드러난 다른 평가셋의 단일 정답 집합 지표였다. 이번 결과와 그대로 개선율로 비교하면 안 된다.', '- 10개 상황을 10가지씩 표현한 합성 질문이다. 100개의 독립 상황·전문가 독립 검수·실사용 정확도가 아니다. 같은 상황군의 표현은 상관된 표본이다. 일반화는 추가 상황군과 실제 사용자 검증이 필요하다.', '- 포괄 목표 50개와 상황·제약 50개를 구분했다. 단일 질문·무관 질문·확인 질문을 정답으로 넣어 분모를 늘리지 않았다. 모든 정답 조합은 최소 2개 메뉴다.', '- 사용자는 여행 외 추천 묶음도 제품 평가 기준으로 승인했다. 이것은 모든 사용자에게 금융상품 가입을 권장한다는 의미가 아니며, 실제 이용 가능성·자격·거래 성공은 검증하지 않았다.', '- 정답과 소스는 API 실행 전에 고정했고 결과를 보고 바꾸지 않았다. 특정 상황용 추천 분기는 추가하지 않았다. 실제 선택/형식 오류는 재시도하지 않았다.', '- 단독 LLM은 간결한 ID·이름·설명 목록을 받는다. 혼합 구조의 JEV는 검색한 후보의 select_when도 받는다. 정의된 두 경로의 비교이며 모든 입력 상세 필드나 모든 단독 프롬프트의 최적화를 통제한 것은 아니다.', '- HTTP 시간은 실제 응답 경로의 LLM/E5/JEV/proxy를 포함한다. 큐 대기·컴파일·모델/임베딩 준비는 제외한다. 각 조건 1회이고 네트워크·캐시·모델 변동성이 있다.', '- 사용자 요청에 따라 한도 오류만 최대 4번까지 교체하고 이전 시도는 별도 보관한다. 그 시도의 토큰은 비교 합계에서 제외한다. 응답에 usage가 없으면 0으로 만들지 않는다. 비교 비용은 전체 청구액이 아니다.', '- 비용은 공개 표준 단가와 관측 usage의 추정이다. 캐시 입력은 전체 입력의 일부다. JEV 출력은 무료이며 제공자별 토큰 총량을 동일 과금 단위로 비교하면 안 된다. 로컬 E5 CPU/호스팅·세금·계정별 요금 차이는 제외한다.', '- 발표 페이지 구성은 취소 상태로 유지했다. GitHub에 게시하지 않았다. 기존 혼합 300문항·이전 비교의 부분 결과와 이번 결과를 합치지 않았다.', '', '단가: [GPT-4.1 공식 모델 문서](https://developers.openai.com/api/docs/models/gpt-4.1), [TypeSafe 공식 요금 안내](https://help.typesafe.ai/articles/5187202169-how-much-does-jev-cost). 2026-11-15 확인. 원본은 run/results.json 및 upstream-calls.jsonl, 기준은 scripts/semantic/situation_goal100/accepted-reference.json, 세부 집계는 summary.json, 실패는 failures.json에 있다.']
(OUT/'README.md').write_text('\n'.join(lines)+'\n');print(json.dumps(summary,ensure_ascii=False));print(diff)
